"""Value objects inmutables del dominio.

Se comparan por valor, no por identidad, y encapsulan las reglas de
validación (dinero exacto en céntimos, SKU no vacío, cantidades >= 1).
"""
from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal


@dataclass(frozen=True, order=True)
class Money:
    """Importe monetario exacto almacenado en céntimos.

    Evita por completo los errores de coma flotante: 0.1 + 0.2 == 0.3.
    """

    cents: int
    currency: str = "EUR"

    def __post_init__(self) -> None:
        if isinstance(self.cents, bool) or not isinstance(self.cents, int):
            raise TypeError("cents debe ser un entero")
        if len(self.currency) != 3 or not self.currency.isalpha():
            raise ValueError("currency debe ser un código ISO 4217 de 3 letras")

    @classmethod
    def from_amount(cls, amount: float | int | str | Decimal, currency: str = "EUR") -> "Money":
        """Crea un Money a partir de un importe decimal (ej. ``12.99``)."""
        cents = (Decimal(str(amount)) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        return cls(int(cents), currency)

    @property
    def amount(self) -> Decimal:
        """Importe como Decimal (solo para mostrar/serializar)."""
        return Decimal(self.cents) / 100

    def __add__(self, other: "Money") -> "Money":
        self._check_currency(other)
        return Money(self.cents + other.cents, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check_currency(other)
        return Money(self.cents - other.cents, self.currency)

    def __mul__(self, factor: int) -> "Money":
        if isinstance(factor, bool) or not isinstance(factor, int):
            raise TypeError("Money solo se puede multiplicar por un entero (cantidad)")
        return Money(self.cents * factor, self.currency)

    __rmul__ = __mul__

    def percentage(self, percent: Decimal | int | str) -> "Money":
        """Devuelve el ``percent``% de este importe, redondeado a céntimo (half-up)."""
        pct = Decimal(str(percent))
        cents = (Decimal(self.cents) * pct / Decimal(100)).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        return Money(int(cents), self.currency)

    def _check_currency(self, other: "Money") -> None:
        if not isinstance(other, Money):
            raise TypeError("Solo se pueden operar objetos Money entre sí")
        if self.currency != other.currency:
            raise ValueError(f"Divisas distintas: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        sign = "-" if self.cents < 0 else ""
        return f"{sign}{self.amount:.2f} {self.currency}"


@dataclass(frozen=True)
class SKU:
    """Identificador de producto (stock keeping unit)."""

    value: str

    def __post_init__(self) -> None:
        if not self.value or not self.value.strip():
            raise ValueError("El SKU no puede estar vacío")
        object.__setattr__(self, "value", self.value.strip())

    def __str__(self) -> str:
        return self.value


@dataclass(frozen=True)
class Quantity:
    """Cantidad de unidades de un producto (entero >= 1)."""

    value: int

    def __post_init__(self) -> None:
        if isinstance(self.value, bool) or not isinstance(self.value, int) or self.value < 1:
            raise ValueError("La cantidad debe ser un entero >= 1")

    def __int__(self) -> int:
        return self.value

    def __str__(self) -> str:
        return str(self.value)

"""Excepciones de dominio del carrito."""


class CartError(Exception):
    """Base de todos los errores del dominio del carrito."""


class CartNotFound(CartError):
    """El carrito solicitado no existe en el repositorio."""


class ProductNotFound(CartError):
    """El SKU no existe en el catálogo."""


class ItemNotInCart(CartError):
    """Se intentó operar con un producto que no está en el carrito."""


class CartLimitExceeded(CartError):
    """Se alcanzó el número máximo de productos distintos por carrito."""


class InsufficientStock(CartError):
    """La cantidad solicitada supera el stock disponible."""


class InvalidQuantity(CartError):
    """La cantidad supera el máximo permitido por producto."""


class EmptyCart(CartError):
    """Operación no permitida sobre un carrito vacío (p. ej. checkout)."""

"""Eventos de dominio y bus de eventos.

Permiten extender el sistema (auditoría, notificaciones, métricas, pedidos...)
sin modificar la lógica del carrito: basta con suscribir un handler.
"""
from __future__ import annotations

import logging
import threading
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Callable, Iterable

from .value_objects import Money

logger = logging.getLogger("cart.events")


@dataclass(frozen=True)
class DomainEvent:
    """Evento base; ``occurred_at`` se rellena solo y es solo-keyword."""

    occurred_at: datetime = field(
        default_factory=lambda: datetime.now(timezone.utc), kw_only=True
    )


@dataclass(frozen=True)
class CartCreated(DomainEvent):
    cart_id: str


@dataclass(frozen=True)
class ItemAdded(DomainEvent):
    cart_id: str
    sku: str
    quantity: int
    new_quantity: int


@dataclass(frozen=True)
class ItemQuantityUpdated(DomainEvent):
    cart_id: str
    sku: str
    quantity: int


@dataclass(frozen=True)
class ItemRemoved(DomainEvent):
    cart_id: str
    sku: str


@dataclass(frozen=True)
class CartCleared(DomainEvent):
    cart_id: str


@dataclass(frozen=True)
class CartCheckedOut(DomainEvent):
    cart_id: str
    total: Money
    item_count: int


@dataclass(frozen=True)
class CartMerged(DomainEvent):
    source_id: str
    target_id: str
    moved_items: int


EventHandler = Callable[[DomainEvent], None]


class EventBus:
    """Bus de eventos en proceso, seguro entre hilos.

    Los handlers se ejecutan de forma aislada: si uno falla, se registra el
    error y no se interrumpe la operación del carrito ni la del resto de handlers.
    Se puede suscribir a ``DomainEvent`` para recibir todos los eventos, o a un
    tipo concreto (p. ej. ``ItemAdded``).
    """

    def __init__(self) -> None:
        self._handlers: dict[type, list[EventHandler]] = defaultdict(list)
        self._lock = threading.Lock()

    def subscribe(self, event_type: type[DomainEvent], handler: EventHandler) -> None:
        with self._lock:
            self._handlers[event_type].append(handler)

    def publish(self, event: DomainEvent) -> None:
        with self._lock:
            handlers: list[EventHandler] = []
            # Recorre el MRO para que suscribirse a DomainEvent capture todo.
            for cls in type(event).__mro__:
                handlers.extend(self._handlers.get(cls, ()))
        for handler in handlers:
            try:
                handler(event)
            except Exception:
                logger.exception("Error en handler de %s", type(event).__name__)

    def publish_all(self, events: Iterable[DomainEvent]) -> None:
        for event in events:
            self.publish(event)

"""Entidades del dominio: Product, CartItem y Cart.

El carrito es seguro entre hilos (RLock interno) y registra eventos de
dominio que el servicio publica tras persistir.
"""
from __future__ import annotations

import threading
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Callable
from uuid import uuid4

from .events import (
    CartCleared,
    DomainEvent,
    ItemAdded,
    ItemQuantityUpdated,
    ItemRemoved,
)
from .exceptions import (
    CartError,
    CartLimitExceeded,
    InsufficientStock,
    InvalidQuantity,
    ItemNotInCart,
    ProductNotFound,
)
from .value_objects import Money, Quantity, SKU


def _now() -> datetime:
    return datetime.now(timezone.utc)


def _as_sku(value: SKU | str) -> SKU:
    return value if isinstance(value, SKU) else SKU(str(value))


@dataclass(frozen=True)
class Product:
    """Producto del catálogo. ``stock=None`` significa stock ilimitado."""

    sku: SKU
    name: str
    price: Money
    stock: int | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.sku, SKU):
            object.__setattr__(self, "sku", SKU(str(self.sku)))
        if self.stock is not None and self.stock < 0:
            raise ValueError("El stock no puede ser negativo")


class CartItem:
    """Línea del carrito: un producto y su cantidad."""

    __slots__ = ("_product", "_quantity")

    def __init__(self, product: Product, quantity: Quantity | int = 1) -> None:
        self._product = product
        self._quantity = quantity if isinstance(quantity, Quantity) else Quantity(quantity)

    @property
    def product(self) -> Product:
        return self._product

    @property
    def quantity(self) -> Quantity:
        return self._quantity

    @property
    def sku(self) -> SKU:
        return self._product.sku

    def set_quantity(self, quantity: Quantity) -> None:
        self._quantity = quantity

    @property
    def line_total(self) -> Money:
        return self._product.price * self._quantity.value

    def __repr__(self) -> str:
        return f"CartItem({self.sku.value!r} x{self._quantity.value})"


class Cart:
    """Carrito de la compra, seguro entre hilos.

    - ``max_items``: límite de SKUs distintos (configurable por carrito).
    - ``MAX_QUANTITY_PER_ITEM``: límite de unidades por SKU.
    - Registra eventos de dominio que se drenan con ``drain_events()``.
    """

    MAX_QUANTITY_PER_ITEM = 999

    def __init__(self, cart_id: str | None = None, max_items: int = 100, currency: str = "EUR") -> None:
        if max_items < 1:
            raise ValueError("max_items debe ser >= 1")
        self.id = cart_id or uuid4().hex
        self.max_items = max_items
        self.currency = currency
        self.created_at = _now()
        self.updated_at = _now()
        self._items: dict[SKU, CartItem] = {}
        self._events: list[DomainEvent] = []
        self._lock = threading.RLock()

    # ------------------------------------------------------------- eventos
    def record_event(self, event: DomainEvent) -> None:
        with self._lock:
            self._events.append(event)

    def drain_events(self) -> list[DomainEvent]:
        with self._lock:
            events = list(self._events)
            self._events.clear()
            return events

    # ---------------------------------------------------------- mutaciones
    def add_item(self, product: Product, quantity: Quantity | int = 1) -> None:
        qty = quantity if isinstance(quantity, Quantity) else Quantity(quantity)
        with self._lock:
            self._check_currency(product.price)
            existing = self._items.get(product.sku)
            new_total = (existing.quantity.value if existing else 0) + qty.value
            self._check_item_limit(new_total)
            self._check_stock(product, new_total)
            if existing:
                existing.set_quantity(Quantity(new_total))
                self.record_event(ItemQuantityUpdated(self.id, product.sku.value, new_total))
            else:
                if len(self._items) >= self.max_items:
                    raise CartLimitExceeded(
                        f"El carrito admite como máximo {self.max_items} productos distintos"
                    )
                self._items[product.sku] = CartItem(product, qty)
                self.record_event(ItemAdded(self.id, product.sku.value, qty.value, new_total))
            self._touch()

    def update_quantity(self, sku: SKU | str, quantity: Quantity | int) -> None:
        sku = _as_sku(sku)
        qty = quantity if isinstance(quantity, Quantity) else Quantity(quantity)
        with self._lock:
            item = self._items.get(sku)
            if item is None:
                raise ItemNotInCart(f"{sku} no está en el carrito")
            self._check_item_limit(qty.value)
            self._check_stock(item.product, qty.value)
            item.set_quantity(qty)
            self.record_event(ItemQuantityUpdated(self.id, sku.value, qty.value))
            self._touch()

    def remove_item(self, sku: SKU | str) -> None:
        sku = _as_sku(sku)
        with self._lock:
            if sku not in self._items:
                raise ItemNotInCart(f"{sku} no está en el carrito")
            del self._items[sku]
            self.record_event(ItemRemoved(self.id, sku.value))
            self._touch()

    def clear(self) -> None:
        with self._lock:
            if self._items:
                self._items.clear()
                self.record_event(CartCleared(self.id))
                self._touch()

    # ------------------------------------------------------------ consultas
    @property
    def items(self) -> list[CartItem]:
        with self._lock:
            return sorted(self._items.values(), key=lambda i: i.sku.value)

    @property
    def subtotal(self) -> Money:
        with self._lock:
            total: Money | None = None
            for item in self._items.values():
                total = item.line_total if total is None else total + item.line_total
            return total if total is not None else Money(0, self.currency)

    @property
    def item_count(self) -> int:
        with self._lock:
            return sum(i.quantity.value for i in self._items.values())

    @property
    def distinct_items(self) -> int:
        with self._lock:
            return len(self._items)

    @property
    def is_empty(self) -> bool:
        return self.distinct_items == 0

    def contains(self, sku: SKU | str) -> bool:
        with self._lock:
            return _as_sku(sku) in self._items

    # ------------------------------------------------------- serialización
    def to_dict(self) -> dict:
        with self._lock:
            return {
                "id": self.id,
                "max_items": self.max_items,
                "currency": self.currency,
                "created_at": self.created_at.isoformat(),
                "updated_at": self.updated_at.isoformat(),
                "items": [
                    {"sku": item.sku.value, "quantity": item.quantity.value}
                    for item in self.items
                ],
            }

    @classmethod
    def from_dict(cls, data: dict, resolve_product: Callable[[SKU], Product]) -> "Cart":
        """Reconstruye un carrito desde su dict; los productos se resuelven
        con ``resolve_product`` (p. ej. ``catalogo.get``)."""
        cart = cls(
            cart_id=data["id"],
            max_items=int(data.get("max_items", 100)),
            currency=data.get("currency", "EUR"),
        )
        cart.created_at = datetime.fromisoformat(data["created_at"])
        cart.updated_at = datetime.fromisoformat(data["updated_at"])
        for raw in data.get("items", []):
            sku = SKU(raw["sku"])
            product = resolve_product(sku)
            if product is None:
                raise ProductNotFound(f"Producto desconocido al restaurar el carrito: {sku}")
            cart._items[sku] = CartItem(product, Quantity(int(raw["quantity"])))
        return cart

    # ------------------------------------------------------------- privados
    def _check_currency(self, price: Money) -> None:
        if price.currency != self.currency:
            raise CartError(
                f"El carrito usa {self.currency} y el producto usa {price.currency}"
            )

    def _check_item_limit(self, qty: int) -> None:
        if qty > self.MAX_QUANTITY_PER_ITEM:
            raise InvalidQuantity(
                f"Máximo {self.MAX_QUANTITY_PER_ITEM} unidades por producto"
            )

    def _check_stock(self, product: Product, qty: int) -> None:
        if product.stock is not None and qty > product.stock:
            raise InsufficientStock(
                f"Stock insuficiente de {product.sku}: solicitadas {qty}, "
                f"disponibles {product.stock}"
            )

    def _touch(self) -> None:
        self.updated_at = _now()

    def __repr__(self) -> str:
        return f"Cart(id={self.id!r}, items={self.distinct_items}, count={self.item_count})"

"""Motor de precios: descuentos e impuestos como estrategias intercambiables.

Añadir una nueva promoción o un nuevo impuesto no requiere tocar el carrito:
basta con implementar el protocolo y añadir la estrategia al motor.
"""
from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal
from typing import Protocol, Sequence

from ..domain.entities import Cart
from ..domain.value_objects import Money


@dataclass(frozen=True)
class ReceiptLine:
    sku: str
    name: str
    unit_price: Money
    quantity: int
    line_total: Money


@dataclass(frozen=True)
class Receipt:
    """Recibo/factura resultado de tasar un carrito."""

    cart_id: str
    lines: tuple[ReceiptLine, ...]
    subtotal: Money
    discount: Money
    tax: Money
    total: Money

    def __str__(self) -> str:
        out = [f"Recibo del carrito {self.cart_id}"]
        for line in self.lines:
            out.append(
                f"  {line.sku}  {line.name}  x{line.quantity} @ {line.unit_price}"
                f" = {line.line_total}"
            )
        out.append(f"  Subtotal : {self.subtotal}")
        if self.discount.cents:
            out.append(f"  Descuento: -{self.discount}")
        if self.tax.cents:
            out.append(f"  Impuestos: {self.tax}")
        out.append(f"  TOTAL    : {self.total}")
        return "\n".join(out)


class DiscountStrategy(Protocol):
    """Estrategia de descuento: devuelve el importe a descontar sobre ``amount``."""

    @property
    def name(self) -> str: ...

    def apply(self, amount: Money) -> Money: ...


class TaxStrategy(Protocol):
    """Estrategia de impuesto: devuelve el importe del impuesto sobre ``amount``."""

    @property
    def name(self) -> str: ...

    def apply(self, amount: Money) -> Money: ...


class PercentageDiscount:
    """Descuento porcentual (p. ej. 10%)."""

    def __init__(self, percent: Decimal | int | str, name: str | None = None) -> None:
        self.percent = Decimal(str(percent))
        if self.percent < 0:
            raise ValueError("El porcentaje de descuento no puede ser negativo")
        self._name = name or f"-{self.percent}%"

    @property
    def name(self) -> str:
        return self._name

    def apply(self, amount: Money) -> Money:
        return amount.percentage(self.percent)


class FixedDiscount:
    """Descuento de importe fijo; nunca descuenta más que el importe dado."""

    def __init__(self, amount: Money, name: str | None = None) -> None:
        self.amount = amount
        self._name = name or f"Cupón {amount}"

    @property
    def name(self) -> str:
        return self._name

    def apply(self, amount: Money) -> Money:
        if self.amount.currency != amount.currency:
            raise ValueError("Divisa del cupón distinta de la del carrito")
        return self.amount if self.amount < amount else amount


class PercentageTax:
    """Impuesto porcentual sobre la base imponible (p. ej. IVA 21%)."""

    def __init__(self, rate: Decimal | int | str, name: str | None = None) -> None:
        self.rate = Decimal(str(rate))
        if self.rate < 0:
            raise ValueError("El tipo de impuesto no puede ser negativo")
        self._name = name or f"Impuesto {self.rate}%"

    @property
    def name(self) -> str:
        return self._name

    def apply(self, amount: Money) -> Money:
        return amount.percentage(self.rate)


class PricingEngine:
    """Tasa un carrito aplicando descuentos (en cadena, sobre el resto) y
    luego impuestos sobre la base imponible resultante."""

    def __init__(
        self,
        discounts: Sequence[DiscountStrategy] = (),
        taxes: Sequence[TaxStrategy] = (),
    ) -> None:
        self.discounts = tuple(discounts)
        self.taxes = tuple(taxes)

    def price(self, cart: Cart) -> Receipt:
        lines = tuple(
            ReceiptLine(
                sku=item.sku.value,
                name=item.product.name,
                unit_price=item.product.price,
                quantity=item.quantity.value,
                line_total=item.line_total,
            )
            for item in cart.items
        )
        subtotal = cart.subtotal
        discount = Money(0, subtotal.currency)
        remaining = subtotal
        for strategy in self.discounts:
            disc = strategy.apply(remaining)
            discount = discount + disc
            remaining = remaining - disc
        tax = Money(0, subtotal.currency)
        for strategy in self.taxes:
            tax = tax + strategy.apply(remaining)
        total = subtotal - discount + tax
        return Receipt(
            cart_id=cart.id,
            lines=lines,
            subtotal=subtotal,
            discount=discount,
            tax=tax,
            total=total,
        )

"""Adaptadores de infraestructura: catálogo y repositorios de carritos.

- ``InMemoryProductCatalog`` / ``InMemoryCartRepository``: para tests y
  procesos efímeros.
- ``SqliteCartRepository``: persistencia real en SQLite (JSON por carrito),
  válida para despliegues que compartan la base de datos.

Cualquier otro adaptador (Redis, PostgreSQL, API externa...) solo tiene que
cumplir los protocolos de ``cart.application.ports``.
"""
from __future__ import annotations

import json
import sqlite3
import threading
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable, Iterable

from ..domain.entities import Cart, Product
from ..domain.exceptions import ProductNotFound
from ..domain.value_objects import SKU


def _as_sku(value: SKU | str) -> SKU:
    return value if isinstance(value, SKU) else SKU(str(value))


class InMemoryProductCatalog:
    """Catálogo en memoria, seguro entre hilos."""

    def __init__(self, products: Iterable[Product] = ()) -> None:
        self._products: dict[SKU, Product] = {}
        self._lock = threading.Lock()
        for product in products:
            self.add(product)

    def add(self, product: Product) -> None:
        with self._lock:
            self._products[product.sku] = product

    def get(self, sku: SKU | str) -> Product | None:
        with self._lock:
            return self._products.get(_as_sku(sku))

    def list(self) -> list[Product]:
        with self._lock:
            return sorted(self._products.values(), key=lambda p: p.sku.value)

    def __len__(self) -> int:
        with self._lock:
            return len(self._products)


class InMemoryCartRepository:
    """Repositorio de carritos en memoria, seguro entre hilos."""

    def __init__(self) -> None:
        self._carts: dict[str, Cart] = {}
        self._lock = threading.Lock()

    def get(self, cart_id: str) -> Cart | None:
        with self._lock:
            return self._carts.get(cart_id)

    def save(self, cart: Cart) -> None:
        with self._lock:
            self._carts[cart.id] = cart

    def delete(self, cart_id: str) -> None:
        with self._lock:
            self._carts.pop(cart_id, None)

    def list_ids(self) -> list[str]:
        with self._lock:
            return sorted(self._carts)

    def __len__(self) -> int:
        with self._lock:
            return len(self._carts)


class SqliteCartRepository:
    """Repositorio persistente en SQLite.

    Cada carrito se guarda como una fila JSON, así que el esquema no cambia
    si evoluciona el dominio. ``product_resolver`` reconstruye los productos
    (p. ej. ``catalogo.get``) al leer.
    """

    def __init__(
        self,
        path: str | Path = ":memory:",
        product_resolver: Callable[[SKU], Product] | None = None,
    ) -> None:
        self._conn = sqlite3.connect(str(path), check_same_thread=False)
        self._conn.execute(
            "CREATE TABLE IF NOT EXISTS carts ("
            "  id TEXT PRIMARY KEY,"
            "  data TEXT NOT NULL,"
            "  updated_at TEXT NOT NULL"
            ")"
        )
        self._conn.commit()
        self._lock = threading.Lock()
        if product_resolver is None:

            def product_resolver(sku: SKU) -> Product:
                raise ProductNotFound(f"Sin resolvedor de productos para {sku}")

        self._resolve = product_resolver

    def get(self, cart_id: str) -> Cart | None:
        with self._lock:
            row = self._conn.execute(
                "SELECT data FROM carts WHERE id = ?", (cart_id,)
            ).fetchone()
        if row is None:
            return None
        return Cart.from_dict(json.loads(row[0]), self._resolve)

    def save(self, cart: Cart) -> None:
        payload = json.dumps(cart.to_dict(), ensure_ascii=False)
        ts = datetime.now(timezone.utc).isoformat()
        with self._lock:
            self._conn.execute(
                "INSERT INTO carts (id, data, updated_at) VALUES (?, ?, ?) "
                "ON CONFLICT(id) DO UPDATE SET data = excluded.data, "
                "updated_at = excluded.updated_at",
                (cart.id, payload, ts),
            )
            self._conn.commit()

    def delete(self, cart_id: str) -> None:
        with self._lock:
            self._conn.execute("DELETE FROM carts WHERE id = ?", (cart_id,))
            self._conn.commit()

    def list_ids(self) -> list[str]:
        with self._lock:
            rows = self._conn.execute("SELECT id FROM carts ORDER BY id").fetchall()
        return [row[0] for row in rows]

    def close(self) -> None:
        with self._lock:
            self._conn.close()
